/**
 * @file red_black_tree.hpp
 * @brief A high-performance, strictly compliant Red-Black Tree implementation in C++17.
 * 
 * This file provides a template-based binary search tree that maintains balance
 * through the following Red-Black Tree properties:
 * 1. Every node is either red or black.
 * 2. The root is black.
 * 3. All leaves (NIL) are black.
 * 4. If a node is red, then both its children are black.
 * 5. For each node, all paths from the node to descendant leaves contain the same number of black nodes.
 * 
 * Complexity Guarantees:
 * - Insert: O(log n)
 * - Erase: O(log n)
 * - Find: O(log n)
 * - Height: O(log n)
 * 
 * Thread Safety:
 * - Not thread-safe. External synchronization required for concurrent access.
 * 
 * Memory Management:
 * - Uses std::unique_ptr for automatic memory management of nodes.
 * - No memory leaks expected under normal operation.
 * 
 * @author AI Assistant
 * @version 1.0.0
 * @date 2023-10-27
 */

#include <iostream>
#include <functional>
#include <memory>
#include <stdexcept>
#include <algorithm>
#include <vector>
#include <cassert>
#include <limits>
#include <string>
#include <sstream>

namespace rbt {

/**
 * @enum Color
 * @brief Represents the color of a node in the Red-Black Tree.
 */
enum class Color {
    RED,    ///< Node is red
    BLACK   ///< Node is black
};

/**
 * @class Node
 * @brief Internal structure representing a node in the Red-Black Tree.
 * 
 * Each node stores:
 * - A key value
 * - Left and right child pointers
 * - Parent pointer (to facilitate rotations and fixes)
 * - Color (RED or BLACK)
 * 
 * @tparam KeyType The type of the key stored in the node.
 */
template <typename KeyType>
class Node {
public:
    KeyType key;                 ///< The key value stored in this node
    Color color;                 ///< The color of this node (RED or BLACK)
    std::unique_ptr<Node> left;  ///< Pointer to the left child
    std::unique_ptr<Node> right; ///< Pointer to the right child
    Node* parent;                ///< Pointer to the parent node (raw pointer for cycle avoidance)

    /**
     * @brief Constructs a new node with the specified key.
     * @param k The key to store in the node.
     * @param c The color of the node (default is RED for new insertions).
     */
    explicit Node(const KeyType& k, Color c = Color::RED)
        : key(k), color(c), left(nullptr), right(nullptr), parent(nullptr) {}

    /**
     * @brief Copy constructor (deleted to prevent accidental copying of tree structure).
     */
    Node(const Node&) = delete;

    /**
     * @brief Copy assignment operator (deleted to prevent accidental copying of tree structure).
     */
    Node& operator=(const Node&) = delete;

    /**
     * @brief Checks if the node has a left child.
     * @return true if left child exists, false otherwise.
     */
    bool hasLeft() const { return left != nullptr; }

    /**
     * @brief Checks if the node has a right child.
     * @return true if right child exists, false otherwise.
     */
    bool hasRight() const { return right != nullptr; }

    /**
     * @brief Checks if the node is a leaf (no children).
     * @return true if the node is a leaf, false otherwise.
     */
    bool isLeaf() const { return !hasLeft() && !hasRight(); }

    /**
     * @brief Checks if the node is red.
     * @return true if the node is red, false otherwise.
     */
    bool isRed() const { return color == Color::RED; }

    /**
     * @brief Checks if the node is black.
     * @return true if the node is black, false otherwise.
     */
    bool isBlack() const { return color == Color::BLACK; }

    /**
     * @brief Returns the left child node.
     * @return Pointer to the left child, or nullptr if none.
     */
    Node* getLeft() { return left.get(); }

